L10: 
L11: > Tiny 200b functional event emitter / pubsub.
L12: 
L13: -   **Microscopic:** weighs less than 200 bytes gzipped
L14: -   **Useful:** a wildcard `"*"` event type listens to all events
L15: -   **Familiar:** same names & ideas as [Node's EventEmitter](https://nodejs.org/api/events.html#events_class_eventemitter)
L16: -   **Functional:** methods don't rely on `this`
L17: -   **Great Name:** somehow [mitt](https://npm.im/mitt) wasn't taken
L18: 
L19: Mitt was made for the browser, but works in any JavaScript runtime. It has no dependencies and supports IE9+."}, {"path": "README.md", "start_line": 81, "end_line": 112, "content": "L81: ### Typescript
L82: 
L83: Set `"strict": true` in your tsconfig.json to get improved type inference for `mitt` instance methods.
L84: 
L85: ```ts
L86: import mitt from 'mitt';
L87: 
L88: type Events = {
L89:   foo: string;
L90:   bar?: number;
L91: };
L92: 
L93: const emitter = mitt<Events>(); // inferred as Emitter<Events>
L94: 
L95: emitter.on('foo', (e) => {}); // 'e' has inferred type 'string'
L96: 
L97: emitter.emit('foo', 42); // Error: Argument of type 'number' is not assignable to parameter of type 'string'. (2345)
L98: ```
L99: 
L100: Alternatively, you can use the provided `Emitter` type:
L101: 
L102: ```ts
L103: import mitt, { Emitter } from 'mitt';
L104: 
L105: type Events = {
L106:   foo: string;
L107:   bar?: number;
L108: };
L109: 
L110: const emitter: Emitter<Events> = mitt<Events>();
L111: ```"}, {"path": "src/index.ts", "start_line": 46, "end_line": 123, "content": "L46: export default function mitt<Events extends Record<EventType, unknown>>(
L47: 	all?: EventHandlerMap<Events>
L48: ): Emitter<Events> {
L49: 	type GenericEventHandler =
L50: 		| Handler<Events[keyof Events]>
L51: 		| WildcardHandler<Events>;
L52: 	all = all || new Map();
L53: 
L54: 	return {
L55: 		/**
L56: 		 * A Map of event names to registered handler functions.
L57: 		 */
L58: 		all,
L59: 
L60: 		/**
L61: 		 * Register an event handler for the given type.
L62: 		 * @param {string|symbol} type Type of event to listen for, or `'*'` for all events
L63: 		 * @param {Function} handler Function to call in response to given event
L64: 		 * @memberOf mitt
L65: 		 */
L66: 		on<Key extends keyof Events>(type: Key, handler: GenericEventHandler) {
L67: 			const handlers: Array<GenericEventHandler> | undefined = all!.get(type);
L68: 			if (handlers) {
L69: 				handlers.push(handler);
L70: 			} else {
L71: 				all!.set(type, [handler] as EventHandlerList<Events[keyof Events]>);
L72: 			}
L73: 		},
L74: 
L75: 		/**
L76: 		 * Remove an event handler for the given type.
L77: 		 * If `handler` is omitted, all handlers of the given type are removed.
L78: 		 * @param {string|symbol} type Type of event to unregister `handler` from (`'*'` to remove a wildcard handler)
L79: 		 * @param {Function} [handler] Handler function to remove
L80: 		 * @memberOf mitt
L81: 		 */
L82: 		off<Key extends keyof Events>(type: Key, handler?: GenericEventHandler) {
L83: 			const handlers: Array<GenericEventHandler> | undefined = all!.get(type);
L84: 			if (handlers) {
L85: 				if (handler) {
L86: 					handlers.splice(handlers.indexOf(handler) >>> 0, 1);
L87: 				} else {
L88: 					all!.set(type, []);
L89: 				}
L90: 			}
L91: 		},
L92: 
L93: 		/**
L94: 		 * Invoke all handlers for the given type.
L95: 		 * If present, `'*'` handlers are invoked after type-matched handlers.
L96: 		 *
L97: 		 * Note: Manually firing '*' handlers is not supported.
L98: 		 *
L99: 		 * @param {string|symbol} type The event type to invoke
L100: 		 * @param {Any} [evt] Any value (object is recommended and powerful), passed to each handler
L101: 		 * @memberOf mitt
L102: 		 */
L103: 		emit<Key extends keyof Events>(type: Key, evt?: Events[Key]) {
L104: 			let handlers = all!.get(type);
L105: 			if (handlers) {
L106: 				(handlers as EventHandlerList<Events[keyof Events]>)
L107: 					.slice()
L108: 					.map((handler) => {
L109: 						handler(evt!);
L110: 					});
L111: 			}
L112: 
L113: 			handlers = all!.get('*');
L114: 			if (handlers) {
L115: 				(handlers as WildCardEventHandlerList<Events>)
L116: 					.slice()
L117: 					.map((handler) => {
L118: 						handler(type, evt!);
L119: 					});
L120: 			}
L121: 		}
L122: 	};
L123: }"}]}

