### Custom Random Bytes Generator

`customRandom` allows you to create a `nanoid` and replace alphabet
and the default random bytes generator.

In this example, a seed-based generator is used:

```js
import { customRandom } from "nanoid";

const rng = seedrandom(seed);
const nanoid = customRandom("abcdef", 10, (size) => {
  return new Uint8Array(size).map(() => 256 * rng());
});

nanoid(); //=> "fbaefaadeb"
```

`random` callback must accept the array size and return an array
with random numbers.

If you want to use the same URL-friendly symbols with `customRandom`,
you can get the default alphabet using the `urlAlphabet`.

```js
import { customRandom, urlAlphabet } from "nanoid";
const nanoid = customRandom(urlAlphabet, 10, random);
```

Note, that between Nano ID versions we may change random generator
call sequence. If you are using seed-based generators, we do not guarantee
the same result.

export function customAlphabet(alphabet, defaultSize = 21) {
  if (
    typeof alphabet !== 'string' ||
    !alphabet ||
    alphabet.length > 256
  ) {
    return customRandom(alphabet, defaultSize, random)
  }
  for (let i = 0; i < alphabet.length; i++) {
    if (alphabet.charCodeAt(i) > 255) {
      // The fast path below writes char codes to a byte buffer,
      // so it supports only single-byte characters.
      return customRandom(alphabet, defaultSize, random)
    }
  }

  // Alphabet char codes to write IDs into a byte buffer directly.
  let charCodes = Uint8Array.from(alphabet, str => {
    return str.charCodeAt(0)
  })
  let alphabetLen = alphabet.length
  // The smallest `2^n - 1` covering all alphabet indexes. Rejecting
  // `byte & mask >= alphabetLen` avoids modulo bias without `%` operation.
  let mask = (2 << (31 - Math.clz32((alphabetLen - 1) | 1))) - 1

  // IDs are pre-generated into a string pool: accepted alphabet chars are
  // written to a byte buffer, converted to a string with one
  // `Buffer#toString()` call, and every ID is a cheap `String#substring()`.
  // It avoids per-character string concatenations and pays string
  // allocation cost once per refill.
  //
  // The pool starts at the first requested size and grows geometrically,
  // so short-living generators do not pay for a full pool.
  let pool = ''
  let poolOffset = 0
  let poolNext = 0

  return (size = defaultSize) => {
    // `|=` convert `size` to number to prevent `valueOf` abusing
    // and pool offset pollution
    size |= 0
    if (size < 0) throw new RangeError('Wrong ID size')
    if (size === 0) return ''
    if (poolOffset + size > pool.length) {
      let target = Math.max(poolNext, size)
      poolNext = Math.min(target * 16, POOL_MAX)
      let buffer = Buffer.allocUnsafe(target)
      if (mask === alphabetLen - 1) {
        // Power-of-two alphabets like `urlAlphabet` accept every byte,
        // so random bytes are translated in place without rejections.
        fillRandom(buffer)
        for (let i = 0; i < target; i++) {
          buffer[i] = charCodes[buffer[i] & mask]
        }
      } else {
        // Rejection sampling accepts `alphabetLen` of every `mask + 1`
        // random bytes. `1.6` requests extra bytes to cover
        // unlucky streaks in most fills.
        let randomBytes = Buffer.allocUnsafe(
          Math.ceil((1.6 * (mask + 1) * target) / alphabetLen)
        )
        let accepted = 0
        while (accepted < target) {
          fillRandom(randomBytes)
          for (let i = 0; i < randomBytes.length; i++) {
            let index = randomBytes[i] & mask
            if (index < alphabetLen) {
              buffer[accepted++] = charCodes[index]
              if (accepted === target) break
            }
          }
        }
      }
      pool = buffer.toString('latin1')
      poolOffset = 0
    }
    poolOffset += size
    return pool.substring(poolOffset - size, poolOffset)
  }
}

### TypeScript

Nano ID 允许将生成的字符串转换为 TypeScript 中的不透明字符串。 例如：

```ts
declare const userIdBrand: unique symbol;
type UserId = string & { [userIdBrand]: true };

// 使用显式类型参数:
mockUser(nanoid<UserId>());

interface User {
  id: UserId;
  name: string;
}

const user: User = {
  // 自动转换为 UserId:
  id: nanoid(),
  name: "Alice",
};
```

test('does not hang on negative size (customAlphabet)', () => {
  equal(customAlphabet('abcdef')(-1), '')
  equal(customAlphabet('abcdef', -5)(), '')
})

describe('customAlphabet', () => {
  test(`has options`, () => {
    let nanoidA = customAlphabet('a', 5)
    equal(nanoidA(), 'aaaaa')
  })

  test(`has flat distribution`, () => {
    let COUNT = 50 * 1000
    let LENGTH = 30
    let ALPHABET = 'abcdefghijklmnopqrstuvwxyz'
    let nanoid2 = customAlphabet(ALPHABET, LENGTH)

    let chars = {}
    for (let i = 0; i < COUNT; i++) {
      let id = nanoid2()
      for (let char of id) {
        if (!chars[char]) chars[char] = 0
        chars[char] += 1
      }
    }

    equal(Object.keys(chars).length, ALPHABET.length)

    let max = 0
    let min = Number.MAX_SAFE_INTEGER
    for (let k in chars) {
      let distribution = (chars[k] * ALPHABET.length) / (COUNT * LENGTH)
      if (distribution > max) max = distribution
      if (distribution < min) min = distribution
    }
    ok(max - min <= 0.05)
  })

  test(`changes size`, () => {
    let nanoidA = customAlphabet('a')
    equal(nanoidA(10), 'aaaaaaaaaa')
  })

  test(`is ready for 0 size`, () => {
    equal(customAlphabet('abc')(0), '')
    equal(customAlphabet('abc', 0)(0), '')
    equal(customAlphabet('')(0), '')
    equal(customAlphabet('', 0)(0), '')
  })

  test(`avoids pool pollution, infinite loop`, () => {
    let ALPHABET = 'abcdefghijklmnopqrstuvwxyz'
    let nanoid2 = customAlphabet(ALPHABET)
    nanoid2(2.1)
    let second = nanoid2()
    let third = nanoid2()
    notEqual(second, third)
  })

  test(`supports multi-byte characters`, () => {
    let ALPHABET = 'абвгд'
    let nanoid2 = customAlphabet(ALPHABET, 10)
    for (let i = 0; i < 100; i++) {
      let id = nanoid2()
      equal(id.length, 10)
      for (let char of id) {
        ok(ALPHABET.includes(char))
      }
    }
  })

  test(`supports alphabets bigger than 256 symbols`, () => {
    equal(customAlphabet('a'.repeat(300))(0), '')
  })

  test(`supports non-string alphabets`, () => {
    let ALPHABET = ['a', 'b', 'c', 'd']
    let nanoid2 = customAlphabet(ALPHABET, 10)
    let id = nanoid2()
    equal(id.length, 10)
    for (let char of id) {
      ok(ALPHABET.includes(char))
    }
  })

  if (type === 'node') {
    test(`does not fall in infinite loop`, () => {
      equal(customAlphabet('abc')(0), '')
      equal(customAlphabet('abc', 0)(0), '')
    })
  }
})

// The string pool optimizations in `customAlphabet()` and `nanoid()`
// were ported from the nope-id project by Orhan Aydoğdu:
// https://github.com/orhanayd/nope-id

// Maximum size of the pre-generated string pool in `customAlphabet()`.
const POOL_MAX = GET_RANDOM_LIMIT / 2

